fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    // If the input has length 0 or 1, return it all in the first vector,
    // with the second vector empty. When len <= 1, the "strictly shorter"
    // requirement does not apply.
    if a.len() <= 1 {
        (a, Vec::new())
    } else {
        // For length >= 2, split off at index 1.
        // `split_off(1)` takes elements from index 1 onward and returns them
        // as a new Vec, leaving `first` with just the element at index 0.
        let mut first = a;
        let second = first.split_off(1);
        (first, second)
    }
}

